/**
 * Contract verification script for dashboard overview mapping
 *
 * Verifies that:
 * 1. Each role's fixture (generated by export:dashboard-fixtures) maps to the expected
 *    non-zero card values.
 * 2. At least 3 non-zero cards are verified per role (Summary >= 15).
 * 3. No mapper reads keys that are absent from the backend response contract.
 * 4. Missing / omitted fields render as '-' instead of masking missing keys as 0.
 *
 * Run from Backend directory via:
 *   npx tsx ../Frontend/scripts/verify-dashboard-contract.ts
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import {
  mapAdminDashboardCards,
  mapCoachDashboardCards,
  mapAthleteDashboardCards,
  mapOrganizerDashboardCards,
  validateOverviewKeys,
} from '../src/lib/dashboardMappers.js';
import type {
  AdminDashboardOverview,
  CoachDashboardOverview,
  AthleteDashboardOverview,
  OrganizerDashboardOverview,
} from '../src/services/academyApi.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

let passed = 0;
let failed = 0;

function assert(condition: boolean, testName: string, detail?: string): void {
  if (condition) {
    console.log(`PASS: ${testName}`);
    passed++;
  } else {
    console.error(`FAIL: ${testName} - ${detail || 'Assertion failed'}`);
    failed++;
  }
}

function loadFixture<T>(fileName: string): T {
  const filePath = path.resolve(__dirname, 'fixtures', fileName);
  if (!fs.existsSync(filePath)) {
    throw new Error(`Fixture file not found: ${filePath}`);
  }
  const content = fs.readFileSync(filePath, 'utf-8');
  return JSON.parse(content) as T;
}

console.log('--- DASHBOARD CONTRACT VERIFICATION SUITE ---\n');

// ============================================================================
// 1. ADMIN DASHBOARD CONTRACT
// ============================================================================
console.log('--- GROUP 1: ADMIN DASHBOARD CONTRACT ---');
const adminFixture = loadFixture<AdminDashboardOverview>('dashboard-admin.json');
const adminCards = mapAdminDashboardCards(adminFixture);

// Non-zero card assertions (>= 3 per role)
assert(
  adminCards.totalUsersRaw === 13,
  'Admin totalUsers matches fixture sum (13)',
  `Expected 13, got ${adminCards.totalUsersRaw}`
);
assert(
  adminCards.totalUsers === '13',
  'Admin totalUsers card renders "13"',
  `Got "${adminCards.totalUsers}"`
);
assert(
  adminCards.activeAthletesRaw === 1,
  'Admin activeAthletes matches fixture count (1)',
  `Expected 1, got ${adminCards.activeAthletesRaw}`
);
assert(
  adminCards.upcomingSessionsRaw === 1,
  'Admin upcomingSessions matches fixture count (1)',
  `Expected 1, got ${adminCards.upcomingSessionsRaw}`
);
assert(
  adminCards.unreadInquiriesRaw === 1,
  'Admin unreadInquiries matches fixture count (1)',
  `Expected 1, got ${adminCards.unreadInquiriesRaw}`
);
assert(
  adminCards.pendingRegistrationsRaw === 1,
  'Admin pendingRegistrations matches fixture count (1)',
  `Expected 1, got ${adminCards.pendingRegistrationsRaw}`
);
assert(
  adminCards.activeTeamsRaw !== null && adminCards.activeTeamsRaw > 0,
  'Admin activeTeams in fixture is > 0',
  `Expected > 0, got ${adminCards.activeTeamsRaw}`
);
assert(
  adminCards.activeTeams === '3',
  'Admin activeTeams card renders "3"',
  `Got "${adminCards.activeTeams}"`
);
assert(
  adminCards.activeCoachesRaw !== null && adminCards.activeCoachesRaw > 0,
  'Admin activeCoaches in fixture is > 0',
  `Expected > 0, got ${adminCards.activeCoachesRaw}`
);
assert(
  adminCards.activeCoaches === '3',
  'Admin activeCoaches card renders "3"',
  `Got "${adminCards.activeCoaches}"`
);

// Verify that an explicitly sent 0 renders "0" while missing key renders "-"
{
  const testExplicitZero = {
    ...adminFixture,
    teams: 0,
    coaches: 0,
  };
  const zeroMapped = mapAdminDashboardCards(testExplicitZero);
  assert(
    zeroMapped.activeTeams === '0' && zeroMapped.activeCoaches === '0',
    'Explicitly sent 0 renders "0" for Admin active teams and coaches',
    `teams: ${zeroMapped.activeTeams}, coaches: ${zeroMapped.activeCoaches}`
  );
}
{
  const testMissingKeys = {
    ...adminFixture,
  };
  delete (testMissingKeys as Record<string, unknown>).teams;
  delete (testMissingKeys as Record<string, unknown>).coaches;
  const missingMapped = mapAdminDashboardCards(testMissingKeys);
  assert(
    missingMapped.activeTeams === '-' && missingMapped.activeCoaches === '-',
    'Missing key renders "-" instead of defaulting silently to 0',
    `teams: ${missingMapped.activeTeams}, coaches: ${missingMapped.activeCoaches}`
  );
}

// ============================================================================
// 2. COACH DASHBOARD CONTRACT
// ============================================================================
console.log('\n--- GROUP 2: COACH DASHBOARD CONTRACT ---');
const coachFixture = loadFixture<CoachDashboardOverview>('dashboard-coach.json');
const coachCards = mapCoachDashboardCards(coachFixture);

assert(
  coachCards.assignedTeamsRaw === 1,
  'Coach assignedTeams matches fixture count (1)',
  `Expected 1, got ${coachCards.assignedTeamsRaw}`
);
assert(
  coachCards.rosteredAthletesRaw === 1,
  'Coach rosteredAthletes matches fixture count (1)',
  `Expected 1, got ${coachCards.rosteredAthletesRaw}`
);
assert(
  coachCards.upcomingDrillsRaw === 1,
  'Coach upcomingDrills matches fixture count (1)',
  `Expected 1, got ${coachCards.upcomingDrillsRaw}`
);
assert(
  coachCards.attendanceRateRaw === 100,
  'Coach attendanceRate matches fixture count (100%)',
  `Expected 100, got ${coachCards.attendanceRateRaw}`
);

// ============================================================================
// 3. ATHLETE DASHBOARD CONTRACT
// ============================================================================
console.log('\n--- GROUP 3: ATHLETE DASHBOARD CONTRACT ---');
const athleteFixture = loadFixture<AthleteDashboardOverview>('dashboard-athlete.json');
const athleteCards = mapAthleteDashboardCards(athleteFixture);

assert(
  athleteCards.attendanceRateRaw === 100,
  'Athlete attendanceRate matches fixture count (100%)',
  `Expected 100, got ${athleteCards.attendanceRateRaw}`
);
assert(
  athleteCards.activeGoalsRaw === 2,
  'Athlete activeGoals matches fixture count (2)',
  `Expected 2, got ${athleteCards.activeGoalsRaw}`
);
assert(
  athleteCards.coachFeedbackRaw === 1,
  'Athlete coachFeedback matches fixture count (1)',
  `Expected 1, got ${athleteCards.coachFeedbackRaw}`
);
assert(
  athleteCards.nextMatchesRaw === 1,
  'Athlete nextMatches matches fixture count (1)',
  `Expected 1, got ${athleteCards.nextMatchesRaw}`
);

// ============================================================================
// 4. ORGANIZER DASHBOARD CONTRACT
// ============================================================================
console.log('\n--- GROUP 4: ORGANIZER DASHBOARD CONTRACT ---');
const organizerFixture = loadFixture<OrganizerDashboardOverview>('dashboard-organizer.json');
const organizerCards = mapOrganizerDashboardCards(organizerFixture);

assert(
  organizerCards.totalTournamentsRaw === 1,
  'Organizer totalTournaments matches fixture count (1)',
  `Expected 1, got ${organizerCards.totalTournamentsRaw}`
);
assert(
  organizerCards.registrationOpenRaw === 1,
  'Organizer registrationOpen matches fixture count (1)',
  `Expected 1, got ${organizerCards.registrationOpenRaw}`
);
assert(
  organizerCards.pendingRegistrationsRaw === 1,
  'Organizer pendingRegistrations matches fixture count (1)',
  `Expected 1, got ${organizerCards.pendingRegistrationsRaw}`
);
assert(
  organizerCards.upcomingMatchesRaw === 1,
  'Organizer upcomingMatches matches fixture count (1)',
  `Expected 1, got ${organizerCards.upcomingMatchesRaw}`
);

// ============================================================================
// 5. CONTRACT SCHEMA & ABSENT KEY VERIFICATION
// ============================================================================
console.log('\n--- GROUP 5: CONTRACT SCHEMA & ABSENT KEY CHECKS ---');

const roles: Array<'Admin' | 'Coach' | 'Athlete' | 'Organizer'> = [
  'Admin',
  'Coach',
  'Athlete',
  'Organizer',
];

for (const r of roles) {
  const fixture = loadFixture<Record<string, unknown>>(`dashboard-${r.toLowerCase()}.json`);
  const validation = validateOverviewKeys(r, fixture);
  assert(
    validation.valid,
    `Fixture dashboard-${r.toLowerCase()}.json contains all expected top-level keys for role ${r}`,
    `Missing keys: ${validation.missingKeys.join(', ')}`
  );
}

// Verify that mappers do NOT read absent keys from fixtures
// Admin absent key test: ensure mapper does not rely on absent .total in userCounts
{
  const missingTotalCounts = {
    role: 'Admin' as const,
    userCounts: { Admin: 2, Coach: 3, Athlete: 5, Organizer: 1 },
    activeAthletes: 5,
    teams: 2,
    coaches: 3,
    upcomingSessions: 1,
    tournaments: { Draft: 0, 'Registration Open': 1, 'In Progress': 0, Completed: 0, Cancelled: 0 },
    pendingRegistrations: 0,
    unreadContactMessages: 0,
  };
  const mapped = mapAdminDashboardCards(missingTotalCounts);
  assert(
    mapped.totalUsers === '11' && mapped.totalUsersRaw === 11,
    'Admin mapper safely computes totalUsers when userCounts has no .total key',
    `Expected 11, got ${mapped.totalUsers}`
  );
}

// Missing field defaults to '-' test: shape mismatch can never masquerade as zero
{
  const incompleteAdmin = { role: 'Admin' as const };
  const incompleteMapped = mapAdminDashboardCards(incompleteAdmin as unknown as AdminDashboardOverview);
  assert(
    incompleteMapped.totalUsers === '-' &&
    incompleteMapped.activeAthletes === '-' &&
    incompleteMapped.activeCoaches === '-' &&
    incompleteMapped.upcomingSessions === '-',
    'Admin mapper replaces missing required fields with visible "-" (never masquerades as 0)',
    `Got totalUsers=${incompleteMapped.totalUsers}, athletes=${incompleteMapped.activeAthletes}`
  );
}

console.log('\n=============================================');
console.log(`SUMMARY: ${passed} passed, ${failed} failed (total: ${passed + failed})`);
console.log('=============================================\n');

if (failed > 0) {
  process.exit(1);
}
